package id.kemkes.satusehat;
import java.net.URI;import java.net.URLEncoder;import java.net.http.*;import java.nio.charset.StandardCharsets;import java.time.*;
final class TokenProvider {private final SatusehatConfig c;private final HttpClient http;private String token;private Instant expires=Instant.EPOCH;TokenProvider(SatusehatConfig c,HttpClient h){this.c=c;this.http=h;} synchronized void invalidate(){token=null;expires=Instant.EPOCH;} synchronized String get() throws Exception{if(token!=null&&Instant.now().isBefore(expires.minusSeconds(60)))return token;String body="client_id="+enc(c.clientId())+"&client_secret="+enc(c.clientSecret());var req=HttpRequest.newBuilder(URI.create(c.oauthBaseUrl()+"/accesstoken?grant_type=client_credentials")).timeout(Duration.ofSeconds(c.timeoutSeconds())).header("Content-Type","application/x-www-form-urlencoded").header("Accept","application/json").POST(HttpRequest.BodyPublishers.ofString(body)).build();var r=http.send(req,HttpResponse.BodyHandlers.ofString());if(r.statusCode()<200||r.statusCode()>299)throw new IllegalStateException("OAuth HTTP "+r.statusCode()+": "+limit(r.body()));token=jsonString(r.body(),"access_token");if(token==null)throw new IllegalStateException("OAuth response missing access_token");String exp=jsonString(r.body(),"expires_in");long seconds=300;try{seconds=Long.parseLong(exp);}catch(Exception ignored){}expires=Instant.now().plusSeconds(seconds);return token;}private static String enc(String s){return URLEncoder.encode(s,StandardCharsets.UTF_8);}private static String jsonString(String json,String key){String marker="\""+key+"\"";int i=json.indexOf(marker);if(i<0)return null;i=json.indexOf(':',i+marker.length());if(i<0)return null;i++;while(i<json.length()&&Character.isWhitespace(json.charAt(i)))i++;if(i>=json.length())return null;if(json.charAt(i)=='\"'){int j=json.indexOf('\"',i+1);return j>i?json.substring(i+1,j):null;}int j=i;while(j<json.length()&&Character.isDigit(json.charAt(j)))j++;return j>i?json.substring(i,j):null;}private static String limit(String s){return s.length()>1000?s.substring(0,1000):s;}}
